# -*- coding: utf-8 -*-
"""Rust for beginners, chapters 6-9."""
import sys, os
sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "..", "cd"))
from clib import *
from rs_a import F, R
CHS = []

CHS.append(CH(
 "Structs and methods",
 ("Structs", []),
 ["A struct groups related values under one name, each with its own field name. It is how you model things like a point, a user, or a rectangle.",
  "Behaviour is attached with an impl block. Functions inside can take self (a method) or not (an associated function such as new).",
  "The #[derive(Debug)] attribute teaches Rust to print your struct with {:?}."],
 [("Struct", "A custom type with named fields."), ("Field", "A named piece of data inside a struct."), ("impl", "A block that adds methods to a type."), ("Method", "A function whose first parameter is self."), ("Associated function", "A function in an impl without self, called with ::."), ("derive", "An attribute that generates standard behaviour such as Debug.")],
 ["struct defines data; impl defines behaviour.", "&self reads, &mut self changes, self consumes.", "Type::new() is an associated function; value.method() is a method.", "#[derive(Debug)] enables {:?}.", "Fields are accessed with a dot."],
 [T("Suppose you want to store a rectangle. Two loose numbers would be easy to mix up. A struct gives them names and keeps them together."),
  R('struct Rect {\n    w: u32,\n    h: u32,\n}\n\nfn main() {\n    let r = Rect { w: 3, h: 4 };\n    println!("{} x {}", r.w, r.h);\n}'),
  T("Now add behaviour. An impl block lists functions that belong to the type. The first parameter of a method is self in one of three flavours: &self to look, &mut self to change, or self to take the value away."),
  F("rs-struct.svg", "The struct holds data. The impl block holds its methods."),
  R('impl Rect {\n    fn new(w: u32, h: u32) -> Rect {\n        Rect { w, h }\n    }\n    fn area(&self) -> u32 {\n        self.w * self.h\n    }\n    fn grow(&mut self) {\n        self.w += 1;\n        self.h += 1;\n    }\n}'),
  T("Rect::new(3, 4) has no self, so you call it with double colons on the type. r.area() has &self, so you call it with a dot on a value. Rust fills in the borrow for you: r.area() automatically borrows r. And grow needs a variable declared with let mut, because it changes the rectangle."),
  T("Debug printing. If you try println!(\"{:?}\", r) on a struct, the compiler says Rect does not implement Debug. The fix is one line above the struct: #[derive(Debug)]. It generates the printing code for you, giving output like Rect { w: 3, h: 4 }. You can add {:#?} for a multi-line pretty version."),
  T("Tuple structs and unit structs. struct Meters(f64); is a struct with unnamed fields, read as m.0. struct Marker; has no fields at all. Both are useful for giving a special name to a simple type."),
  T("Struct update syntax lets you copy most fields from another value: Rect { w: 10, ..old }. Remember ownership: fields that are not Copy are moved out of old.")],
 [("What does impl do?", ["Adds methods to a type", "Imports a library", "Prints a value", "Defines a loop"], 0, "Behaviour for the type."),
  ("What does &mut self mean?", ["The method can change the value", "The method deletes it", "The method copies it", "Nothing"], 0, "Mutable borrow of self."),
  ("How do you call an associated function like new?", ["Rect::new(3, 4)", "r.new(3, 4)", "new Rect", "Rect.new"], 0, "Double colon."),
  ("How do you enable {:?} for a struct?", ["#[derive(Debug)]", "debug!", "impl Print", "It is automatic"], 0, "An attribute."),
  ("How do you read a field?", ["r.w", "r->w", "r::w", "r[w]"], 0, "A dot.")],
 [("struct", "Named fields"), ("impl", "Methods and associated functions"), ("self / &self / &mut self", "Own / read / change"), ("derive(Debug)", "Gives {:?} printing")],
 [MATCH("Match the self", "Pair each form with its use.", [("&self", "read only"), ("&mut self", "change the value"), ("self", "take the value away"), ("no self", "associated function")]),
  FILL("Rectangles", "A struct is defined with the word {{struct}}. Methods go in an {{impl}} block. To print with {:?} you add {{derive}}(Debug). A method that changes the value takes {{&mut self}}."),
  ORDER("Build a type", "Order the steps.", ["Define the struct and its fields", "Open an impl block", "Add new and methods", "Create a value and call a method"])]))

CHS.append(CH(
 "Enums and pattern matching",
 ("Enums", []),
 ["An enum is a type that can be exactly one of several variants. Each variant can carry its own data. Combined with match, enums let you describe choices precisely and have the compiler check that you handled them all.",
  "Rust has no null. Instead it has Option, an enum with Some(value) and None, so the type itself tells you when a value might be missing.",
  "match, if let and while let take values apart by shape."],
 [("Enum", "A type with several possible variants."), ("Variant", "One of the options of an enum."), ("match", "Compares a value against patterns, running the first that fits."), ("Pattern", "A shape that values are matched against."), ("Option", "An enum that is Some(value) or None."), ("Exhaustive", "Covering every possible case.")],
 ["An enum value is exactly one variant.", "Variants can hold data of different shapes.", "match must cover all cases or the compiler refuses.", "Option replaces null: Some(x) or None.", "if let is a shorthand for matching one pattern."],
 [T("Think about a traffic light. It is always exactly one of red, yellow or green. An enum models that: you list the possible states, and a value holds exactly one."),
  R('enum Light {\n    Red,\n    Yellow,\n    Green,\n}\n\nfn main() {\n    let l = Light::Green;\n    match l {\n        Light::Red => println!("stop"),\n        Light::Yellow => println!("slow"),\n        Light::Green => println!("go"),\n    }\n}'),
  T("The key feature of match is that it must be exhaustive. If you delete the Green arm, the program will not compile and the error tells you which variant you missed. When you later add a fourth colour to the enum, every match that does not handle it fails to compile. The compiler finds every place you need to update."),
  T("Variants can carry data, and each variant can carry a different shape of data."),
  R('enum Shape {\n    Circle(f64),\n    Rect { w: f64, h: f64 },\n    Point,\n}\n\nfn area(s: &Shape) -> f64 {\n    match s {\n        Shape::Circle(r) => 3.14 * r * r,\n        Shape::Rect { w, h } => w * h,\n        Shape::Point => 0.0,\n    }\n}'),
  F("rs-enum.svg", "Each variant has its own shape, and each gets its own match arm."),
  T("Patterns bind names. In Shape::Circle(r), the radius is bound to the name r for use in that arm. You can also match ranges (90..=100), alternatives (1 | 2), and add a guard with if: n if n < 0 => ... ."),
  T("Null is famous as a billion-dollar mistake: a value that might secretly be missing makes programs crash. Rust has no null. Instead the standard library has Option<T>, defined as an enum with two variants: Some(value) and None. A function that might not find something returns an Option, and the compiler makes you handle the None case before you use the value."),
  F("rs-option.svg", "Option is either a box with a value or an empty box."),
  R('fn safe_div(a: i32, b: i32) -> Option<i32> {\n    if b == 0 { None } else { Some(a / b) }\n}\n\nfn main() {\n    match safe_div(10, 2) {\n        Some(x) => println!("got {}", x),\n        None => println!("cannot divide"),\n    }\n    if let Some(x) = safe_div(8, 2) {\n        println!("also {}", x);\n    }\n}'),
  T("if let is for when you only care about one case. And you will meet helper methods on Option all the time: unwrap_or(default), map, is_some, and the dangerous unwrap, which panics on None. Use unwrap only for quick experiments or when you are certain.")],
 [("What is an enum value?", ["Exactly one of its variants", "A list of all variants", "A number", "A function"], 0, "One at a time."),
  ("What does exhaustive mean for match?", ["Every case is handled", "It is very long", "It loops forever", "It uses all memory"], 0, "No case missing."),
  ("Which type replaces null in Rust?", ["Option", "Maybe", "Nil", "Void"], 0, "Some or None."),
  ("What does if let Some(x) = opt do?", ["Runs the block when opt holds a value", "Always runs", "Creates an Option", "Panics on None"], 0, "A short match."),
  ("What does a missing match arm cause?", ["A compile error", "A runtime warning", "Nothing", "A slower program"], 0, "E0004.")],
 [("enum", "One of several variants"), ("match", "Must cover every case"), ("Option", "Some(x) or None, no null"), ("if let", "Match one case only")],
 [MATCH("Match the term", "Pair each with its meaning.", [("Variant", "one choice of an enum"), ("Pattern", "a shape to match against"), ("Some", "an Option holding a value"), ("None", "an empty Option")]),
  FILL("Matching", "An {{enum}} is exactly one variant. A {{match}} must be exhaustive. Rust has no null, it has {{Option}}. Use {{if let}} to handle just one case."),
  ORDER("Handle a maybe", "Order the steps for dividing safely.", ["Check whether the divisor is zero", "Return None if it is", "Return Some of the result otherwise", "Match on the Option in the caller"])]))

CHS.append(CH(
 "Collections: Vec, String and HashMap",
 ("Collections", []),
 ["Most programs need to hold many values. The three workhorses are Vec (a growable list), String (growable text) and HashMap (look things up by key).",
  "They all live on the heap and own their contents, so they follow the ownership rules you already know.",
  "Strings need extra care because they are UTF-8: a character can be more than one byte."],
 [("Vec", "A growable ordered list of one type."), ("String", "Growable owned UTF-8 text."), ("HashMap", "A collection mapping keys to values."), ("Index", "A position, starting at 0."), ("Entry", "A HashMap slot you can fill if empty."), ("UTF-8", "Text encoding where characters take 1 to 4 bytes.")],
 ["Vec: push, pop, index, iterate.", "Out-of-range index panics; get returns an Option.", "String len counts bytes, chars() counts characters.", "HashMap: insert, get, entry().or_insert().", "Collections own their data."],
 [T("A Vec is like a train that can add carriages. All carriages hold the same kind of thing, and each has a number starting at zero."),
  F("rs-vec.svg", "A Vec is an ordered list; a HashMap finds a value from a key."),
  R('fn main() {\n    let mut v = vec![1, 2, 3];\n    v.push(4);\n    let last = v.pop();\n    println!("{:?} {:?}", v, last);\n    for x in &v {\n        println!("{}", x);\n    }\n}'),
  T("Indexing with v[10] on a list of three panics. When the position might not exist, use v.get(10), which returns an Option, so you must decide what to do about None. Looping with for x in &v borrows the list and leaves it usable afterwards. for x in v would move it."),
  T("Strings. String::from(\"hi\") makes an owned, growable String. push_str adds text, push adds one character, and + joins (it takes ownership of the left side). format! builds a new string without moving anything, which is usually easiest."),
  T("You cannot index a string with s[0], because characters are not all one byte long. The word héllo has 5 characters but 6 bytes, since é takes two. s.len() says 6. s.chars().count() says 5. Slicing &s[0..2] works on byte positions and panics if you cut through the middle of a character."),
  T("HashMap. Use it to count things or look things up. entry gives you a slot, and or_insert fills it if it was empty. The star dereferences the reference to the number inside."),
  R('use std::collections::HashMap;\n\nfn main() {\n    let mut counts = HashMap::new();\n    for w in "a b a".split_whitespace() {\n        *counts.entry(w).or_insert(0) += 1;\n    }\n    println!("{}", counts["a"]);\n}'),
  T("The order in which a HashMap yields its entries is not guaranteed, so never depend on it. If you need sorted output, collect the keys into a Vec and sort it. Also useful: sort() and dedup() on a Vec, contains, iter().sum(), and len().")],
 [("What does v.pop() return?", ["An Option of the last item", "The first item", "Nothing", "The length"], 0, "Option, because the list may be empty."),
  ("What does indexing past the end do?", ["Panics", "Returns zero", "Returns None", "Grows the Vec"], 0, "Panic; use get for an Option."),
  ("What does \"héllo\".len() return?", ["6", "5", "4", "7"], 0, "Bytes, not characters."),
  ("Which method counts characters?", ["chars().count()", "len()", "size()", "bytes()"], 0, "Characters, not bytes."),
  ("What does entry(k).or_insert(0) do?", ["Inserts 0 if the key is missing and gives access to the value", "Deletes the key", "Sorts the map", "Copies the map"], 0, "Fill if empty.")],
 [("Vec", "Growable list; get for safe access"), ("String", "UTF-8: len is bytes"), ("HashMap", "Key to value, order not guaranteed"), ("entry().or_insert()", "Count things")],
 [MATCH("Match the collection", "Pair each with its use.", [("Vec", "ordered growable list"), ("String", "growable text"), ("HashMap", "look up by key"), ("get", "safe access returning Option")]),
  FILL("Collections", "A {{Vec}} grows with push. Indexing past the end {{panics}}. The length of a String counts {{bytes}}. A {{HashMap}} maps keys to values."),
  ORDER("Count words", "Order the steps.", ["Create an empty HashMap", "Split the text into words", "Use entry and or_insert for each word", "Read the counts"])]))

CHS.append(CH(
 "Handling errors",
 ("Errors", []),
 ["Things go wrong: files are missing, text is not a number, networks fail. Rust splits problems into two kinds: bugs that should stop the program (panics) and expected problems that the caller can handle (Result).",
  "Result is an enum with Ok(value) and Err(error). You must deal with both, either by matching, by providing a fallback, or by passing the error up with the question mark operator.",
  "The type system makes error handling visible: if a function can fail, its signature says so."],
 [("Panic", "An unrecoverable error that stops the program."), ("Result", "An enum: Ok(value) or Err(error)."), ("unwrap", "Takes the value or panics."), ("? operator", "On Err, return it from the function; on Ok, take the value."), ("Propagate", "Pass an error up to the caller."), ("expect", "Like unwrap but with your own panic message.")],
 ["Panic for bugs; Result for expected failures.", "Result<T, E> is Ok(T) or Err(E).", "unwrap and expect panic on Err.", "? returns the error early or unwraps the value.", "The function must itself return a Result to use ?."],
 [T("When a restaurant is out of an ingredient, the waiter does not set the kitchen on fire. They come back and tell you, and you choose something else. A Result is that message: either here is your dish or sorry, here is the problem."),
  T("Panics. A panic prints a message, stops the program and exits with code 101. They happen for bugs such as an index out of range, dividing by zero, integer overflow, or calling unwrap on None. Our lab prints the same message Rust would: thread main panicked at the line and column, then what went wrong."),
  R('fn main() {\n    let v: Vec<i32> = Vec::new();\n    let first = v.first().unwrap_or(&0);\n    println!("{}", first);\n}'),
  T("Prefer a fallback such as unwrap_or when a default makes sense. Use unwrap only when it truly cannot fail, and expect(\"reason\") when you want a clearer message."),
  T("Result. A function that can fail says so in its type: Result<u8, String> means it gives back a u8 or an error message."),
  R('fn parse_age(s: &str) -> Result<u8, String> {\n    match s.parse::<u8>() {\n        Ok(n) => Ok(n),\n        Err(_) => Err(String::from("not a number")),\n    }\n}'),
  F("rs-result.svg", "Result has two paths. The question mark follows the success path or returns the error."),
  T("The ? operator. Matching on every call gets long. Put ? after a call that returns a Result: on Ok it unwraps the value and continues; on Err it returns that error from your function immediately. The enclosing function must return a compatible Result."),
  R('fn add(a: &str, b: &str) -> Result<i32, std::num::ParseIntError> {\n    let x = a.parse::<i32>()?;\n    let y = b.parse::<i32>()?;\n    Ok(x + y)\n}'),
  T("In bigger programs you define your own error enum with a variant for each way things can fail, so callers can match on what went wrong. The same ideas apply: return Result, use ? to pass errors up, and decide at the top (usually main) what to tell the user.")],
 [("What does a panic do?", ["Stops the program with a message", "Retries the call", "Returns None", "Is ignored"], 0, "Exit code 101."),
  ("What are the variants of Result?", ["Ok and Err", "Some and None", "True and False", "Yes and No"], 0, "Success or error."),
  ("What does ? do on an Err?", ["Returns the error from the current function", "Panics", "Ignores it", "Prints it"], 0, "Early return."),
  ("Which is better when a sensible default exists?", ["unwrap_or", "unwrap", "panic!", "loop"], 0, "Provide a fallback."),
  ("Where can you use ?", ["In a function that returns a Result or Option", "Anywhere", "Only in main with no return", "Only in loops"], 0, "The return type must match.")],
 [("Panic", "For bugs"), ("Result", "For expected failures"), ("?", "Propagate errors in one character"), ("unwrap_or", "Provide a default")],
 [MATCH("Match the tool", "Pair each with its job.", [("panic!", "stop on a bug"), ("Result", "report an expected failure"), ("?", "pass an error up"), ("unwrap_or", "use a default instead")]),
  FILL("Failing well", "A {{Result}} is Ok or {{Err}}. The {{?}} operator passes an error up. Calling {{unwrap}} on an Err panics."),
  ORDER("Parse safely", "Order the steps.", ["Call parse on the text", "Get a Result", "Handle Ok with the number", "Handle Err with a message"])]))
